import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BW2T23B9.js";const _=JSON.parse('{"title":"AI 控制模式（创作者视角）","description":"旧版存在过的 sovereign 档已移除：持久化里残留的非法值会在加载时降级为 copilot。","frontmatter":{"description":"旧版存在过的 sovereign 档已移除：持久化里残留的非法值会在加载时降级为 copilot。"},"headers":[],"relativePath":"authoring/ai-control-modes.md","filePath":"authoring/ai-control-modes.md","lastUpdated":1787830168000}'),i={name:"authoring/ai-control-modes.md"};function s(r,t,c,l,n,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="ai-控制模式-创作者视角" tabindex="-1">AI 控制模式（创作者视角） <a class="header-anchor" href="#ai-控制模式-创作者视角" aria-label="Permalink to &quot;AI 控制模式（创作者视角）&quot;">​</a></h1><blockquote><p><code>tool/gui</code> 的 AI 介入度由<strong>一个四档体验模式</strong> + <strong>一组能力开关</strong> + <strong>每日配额熔断</strong>组合决定。本文是这套控制面的索引与安全档位手册。</p><p>唯一真源：<code>tool/gui/src/backend/experience/policy.py</code> 的 <code>resolve_policy()</code>；切换与降档助手在 <code>tool/gui/src/application/presence_mode.py</code>。</p></blockquote><h2 id="_1-四档体验模式" tabindex="-1">1. 四档体验模式 <a class="header-anchor" href="#_1-四档体验模式" aria-label="Permalink to &quot;1. 四档体验模式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────── Immersive ────────────┐</span></span>
<span class="line"><span>│  presence_level = 3               │  全权自动应用 / runtime_opaque（子开关可关）</span></span>
<span class="line"><span>│  含 Active 捆绑；出站操作仍拒绝     │  切入时弹风险确认；Ctrl+Shift+D 一键降档</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>├────────────── Active ─────────────┤</span></span>
<span class="line"><span>│  presence_level = 2               │  active bundle 自动开：</span></span>
<span class="line"><span>│                                   │  Soft / Ambient / Defer / 战役</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>├────────────── Copilot ────────────┤</span></span>
<span class="line"><span>│  presence_level = 1（默认）        │  AI 写动作逐项确认</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>├───────────── Observer ────────────┤</span></span>
<span class="line"><span>│  presence_level = 0               │  零 AI 写 / 零侧效应；</span></span>
<span class="line"><span>│                                   │  危险 / Soft / 意图 / Goal 强制 False</span></span>
<span class="line"><span>└───────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>模式</th><th style="text-align:right;">presence_level</th><th>含义</th></tr></thead><tbody><tr><td><code>observer</code></td><td style="text-align:right;">0</td><td>只诊断不动手；AI 仅给建议，任何写动作 deny</td></tr><tr><td><code>copilot</code></td><td style="text-align:right;">1</td><td>副驾驶（默认）；AI 写动作都需作者确认</td></tr><tr><td><code>active</code></td><td style="text-align:right;">2</td><td>主动；自动捆绑 Soft 自动修 / 伴随建议 / Defer / 战役队列</td></tr><tr><td><code>immersive</code></td><td style="text-align:right;">3</td><td>沉浸；白名单技能可跳过确认静默改课（仍入 Undo）</td></tr></tbody></table><p>切换入口：</p><table tabindex="0"><thead><tr><th>入口</th><th>行为</th></tr></thead><tbody><tr><td>状态栏「模式」chip</td><td>弹出下拉，自由切换四档</td></tr><tr><td>设置 → 体验 OS</td><td>模式选择 + Immersive 子开关 + 能力开关 + 日配额</td></tr><tr><td><code>Ctrl+Shift+D</code></td><td>任何模式一键降档回 <code>copilot</code>（同时使 auto-apply token 失效）</td></tr><tr><td>切入 <code>immersive</code></td><td>弹「切换到 Immersive 全权自治？」风险确认（<code>IMMERSIVE_WARN_TEXT</code>）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">迁移说明</p><p>旧版存在过的 <code>sovereign</code> 档已移除：持久化里残留的非法值会在加载时降级为 <code>copilot</code>。</p></div><h2 id="_2-policydecision-字段" tabindex="-1">2. PolicyDecision 字段 <a class="header-anchor" href="#_2-policydecision-字段" aria-label="Permalink to &quot;2. PolicyDecision 字段&quot;">​</a></h2><p><code>resolve_policy(settings)</code> 返回一个 <code>PolicyDecision</code>，派发点统一读它而不读原始设置：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>含义</th></tr></thead><tbody><tr><td><code>mode</code></td><td>str</td><td>归一化后的模式</td></tr><tr><td><code>presence_level</code></td><td>int</td><td>0–3</td></tr><tr><td><code>allow_dangerous</code></td><td>bool</td><td>危险技能（删 id / 跨节改写 / Hard import）；需 <code>experience_allow_dangerous_skills</code>，observer 强制 False；immersive 全权时自动 True</td></tr><tr><td><code>allow_soft</code></td><td>bool</td><td>Soft Autopilot（卫生规则自动修）；开关或 active bundle 触发</td></tr><tr><td><code>allow_ambient_live</code></td><td>bool</td><td>Ambient 实时提示；开关或 active bundle</td></tr><tr><td><code>allow_defer_resurface</code></td><td>bool</td><td>Defer 重浮；开关或 active bundle</td></tr><tr><td><code>allow_campaign_auto</code></td><td>bool</td><td>战役队列自动浮现；active bundle 恒 True</td></tr><tr><td><code>allow_full_auto_apply</code></td><td>bool</td><td>仅 <code>immersive</code> + <code>experience_immersive_full_auto</code>（默认开）</td></tr><tr><td><code>runtime_opaque</code></td><td>bool</td><td>仅 <code>immersive</code> + <code>experience_immersive_opaque</code>（默认开）</td></tr><tr><td><code>allow_autonomous_write</code></td><td>bool</td><td>= <code>allow_full_auto_apply</code>；observer 恒 False</td></tr><tr><td><code>scope_cross_section</code></td><td>bool</td><td>跨节改写；= <code>allow_dangerous</code></td></tr><tr><td><code>allow_llm_intent</code></td><td>bool</td><td>⌘K LLM 意图分类；需开关 + 非 observer + 配额内</td></tr><tr><td><code>allow_goal</code></td><td>bool</td><td>Goal 规划器入口；需开关 + 非 observer + 配额内</td></tr><tr><td><code>allow_ai_skill</code></td><td>bool</td><td>整体 AI 技能开关；配额超限时 False</td></tr><tr><td><code>budget_exceeded</code> / <code>budget_limit</code> / <code>budget_used</code></td><td>bool / int / int</td><td>M-08 日配额状态；<code>budget_limit=0</code> 表示关闭熔断</td></tr></tbody></table><p>派发规则（<code>can_dispatch</code>）：</p><ul><li><code>app.*</code> 内建动作（保存 / undo / why / pin / help）永远放行。</li><li>observer 下，任何 <code>needs_confirm=True</code> 的非 <code>app.*</code> 动作 deny —— 零 AI 写。</li><li>危险动作需 <code>allow_dangerous</code>；但 immersive 全权时直接放行，由 <code>auto_apply</code> 决定是静默执行还是回落确认。</li><li><code>goal.*</code> 需 <code>allow_goal</code>（或 <code>allow_autonomous_write</code>）。</li><li>配额超限时，仅拦 <code>needs_confirm=True</code> 且非 <code>soft.*</code> / <code>app.*</code> 的 AI 写技能；手编、保存、Soft 不受影响。</li><li><code>is_denied_immersive()</code> 绝对禁区集合（出站 publish / git.push 等）在任何模式都拒绝。</li></ul><h2 id="_3-能力开关-设置-→-体验-os" tabindex="-1">3. 能力开关（设置 → 体验 OS） <a class="header-anchor" href="#_3-能力开关-设置-→-体验-os" aria-label="Permalink to &quot;3. 能力开关（设置 → 体验 OS）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>experience_allow_dangerous_skills</code></td><td>False</td><td>允许危险技能（删 id / 跨节改写 / Hard import）</td></tr><tr><td><code>experience_goal_enabled</code></td><td>False</td><td>启用 Goal 目标规划（多步沙箱草稿；合并仍需确认）</td></tr><tr><td><code>experience_llm_intent</code></td><td>False</td><td>⌘K 自然语言意图分类（调 chat 小模型；关则仅斜杠命令 + 本地规则）</td></tr><tr><td><code>experience_immersive_full_auto</code></td><td>True</td><td>Immersive 档下允许跳过确认自动应用（仍可 Ctrl+Z）</td></tr><tr><td><code>experience_immersive_opaque</code></td><td>True</td><td>Immersive 档下运行时不透明（状态栏仅提示计数）；审计日志始终记录</td></tr><tr><td><code>experience_daily_ai_budget</code></td><td>0</td><td>今日 AI 请求配额；0 = 不限，超限只拦 AI 写技能</td></tr></tbody></table><h2 id="_4-其他独立控制面" tabindex="-1">4. 其他独立控制面 <a class="header-anchor" href="#_4-其他独立控制面" aria-label="Permalink to &quot;4. 其他独立控制面&quot;">​</a></h2><h3 id="_4-1-ai-生成模式" tabindex="-1">4.1 AI 生成模式 <a class="header-anchor" href="#_4-1-ai-生成模式" aria-label="Permalink to &quot;4.1 AI 生成模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>取值</th><th>实现</th><th>适用</th></tr></thead><tbody><tr><td><code>fast</code></td><td><code>backend/ai_generator.generate_with_validate_loop</code> 一次出 Section 草稿</td><td>草稿探索</td></tr><tr><td><code>phased</code> / <code>refine</code></td><td><code>backend/ai_phased</code> 大纲→分课→校验→质量→修复→解释</td><td>发布候选</td></tr></tbody></table><p>入口：工坊 <strong>生成模式</strong> 下拉（<code>fast</code> 默认）；QSettings <code>ai/pipeline_default_mode</code>。</p><h3 id="_4-2-json-schema-严格度" tabindex="-1">4.2 JSON Schema 严格度 <a class="header-anchor" href="#_4-2-json-schema-严格度" aria-label="Permalink to &quot;4.2 JSON Schema 严格度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>取值</th><th>行为</th></tr></thead><tbody><tr><td><code>auto</code>（默认）</td><td>首次 <code>json_schema</code> 试错遇 400 时调 <code>mark_json_schema_unsupported()</code>，后续切 <code>json_object</code></td></tr><tr><td><code>on</code></td><td>强制 <code>json_schema</code>；不接受 400 回退</td></tr><tr><td><code>off</code></td><td>强制 <code>json_object</code>；从不试 <code>json_schema</code></td></tr></tbody></table><h3 id="_4-3-ai-对话模式" tabindex="-1">4.3 AI 对话模式 <a class="header-anchor" href="#_4-3-ai-对话模式" aria-label="Permalink to &quot;4.3 AI 对话模式&quot;">​</a></h3><p><code>ai_generator_dialog.py</code> 的 <code>mode_combo</code>：</p><table tabindex="0"><thead><tr><th>取值</th><th>行为</th></tr></thead><tbody><tr><td><code>normal</code></td><td>直接生成，diff 预览，确认</td></tr><tr><td><code>wish</code>（许愿模式）</td><td>自由对话 + 模板 + 附件；许愿式触发</td></tr></tbody></table><h3 id="_4-4-抽取模式" tabindex="-1">4.4 抽取模式 <a class="header-anchor" href="#_4-4-抽取模式" aria-label="Permalink to &quot;4.4 抽取模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>取值</th><th>触发</th><th>行为</th></tr></thead><tbody><tr><td><code>standard</code></td><td>首次抽取</td><td>抽词汇 + 表达 + 语法点；失败时自动级联</td></tr><tr><td><code>vocab_only</code></td><td>自动级联 / 人工选择</td><td>仅抽词汇</td></tr></tbody></table><p>级联开关：<code>textbook/auto_cascade</code>（默认开）。</p><h3 id="_4-5-ai-助手粒度" tabindex="-1">4.5 AI 助手粒度 <a class="header-anchor" href="#_4-5-ai-助手粒度" aria-label="Permalink to &quot;4.5 AI 助手粒度&quot;">​</a></h3><p><code>backend/experience/handlers/</code> 下 AI 助手按节点粒度运行：<code>lesson</code>（整课重写 / 重生成）或 <code>item</code>（单 Interaction 改写）。</p><h3 id="_4-6-导入目标模式" tabindex="-1">4.6 导入目标模式 <a class="header-anchor" href="#_4-6-导入目标模式" aria-label="Permalink to &quot;4.6 导入目标模式&quot;">​</a></h3><p>工坊草稿导入主窗口课程树时的目标选择：<code>into_section</code>（新 Section）/ <code>into_unit</code>（追加到已有 Unit）/ <code>merge_existing_section</code>（合并）/ <code>replace_section</code>（整体替换，高风险需 dangerous）。</p><h3 id="_4-7-模型路由" tabindex="-1">4.7 模型路由 <a class="header-anchor" href="#_4-7-模型路由" aria-label="Permalink to &quot;4.7 模型路由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>取值</th><th>用途</th></tr></thead><tbody><tr><td><code>model</code>（主模型）</td><td>默认；未分流时所有调用走它</td></tr><tr><td><code>model_chat</code></td><td>对话 / 解释；空时回退 <code>model</code></td></tr><tr><td><code>model_json</code></td><td>JSON 生成 / 修复；空时回退 <code>model</code></td></tr></tbody></table><p>入口：设置 → AI 配置。字段见 <a href="/docs/authoring/ai-course-generation">AI 课程生成 - 字段表</a>。</p><h2 id="_5-m-08-每日-ai-配额" tabindex="-1">5. M-08 每日 AI 配额 <a class="header-anchor" href="#_5-m-08-每日-ai-配额" aria-label="Permalink to &quot;5. M-08 每日 AI 配额&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">budget_limit    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> settings.experience_daily_ai_budget  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 0 = 关闭</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">budget_used     </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> usage_today[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;requests&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># telemetry 累计</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">budget_exceeded </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> budget_limit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> and</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> budget_used </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> budget_limit</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">allow_ai_skill  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> budget_exceeded</span></span></code></pre></div><ul><li>配额<strong>不</strong>影响手编、保存、<code>app.*</code>、<code>soft.*</code> 动作。</li><li>配额<strong>仅</strong>拦截 <code>needs_confirm=True</code> 且非 <code>soft.*</code> / <code>app.*</code> 的 AI 写动作。</li><li>配额超限时状态栏显示「今日 AI 配额已用尽（X/Y）」。</li><li>配额与模式正交：observer 下配额依然计数，但不触发任何写。</li></ul><h2 id="_6-soft-autopilot-与-ambient" tabindex="-1">6. Soft Autopilot 与 ambient <a class="header-anchor" href="#_6-soft-autopilot-与-ambient" aria-label="Permalink to &quot;6. Soft Autopilot 与 ambient&quot;">​</a></h2><p><code>backend/experience/soft_autopilot.py</code> 实现纯规则修复（无 LLM）：</p><table tabindex="0"><thead><tr><th>规则 ID</th><th>行为</th></tr></thead><tbody><tr><td><code>hygiene.trim_whitespace</code></td><td>词条 term / translation / pronunciation 首尾空白</td></tr><tr><td><code>hygiene.collapse_repeated_spaces</code></td><td>内部 ≥2 空白折叠为 1</td></tr><tr><td><code>hygiene.strip_surround_quotes</code></td><td>配对的引号 / 括号包裹剥离</td></tr><tr><td><code>hygiene.drop_empty_tags</code></td><td>删除空 / 非字符串 tag</td></tr><tr><td><code>hygiene.strip_zero_width</code></td><td>移除 U+200B / U+FEFF / U+200C / U+200D</td></tr></tbody></table><p>红线（<strong>永久不下放</strong>）：不做 Hard import、不改 id、不做 section merge、不调 LLM。</p><p>ambient live 提示默认关；<code>active</code> 档自动开启。</p><h2 id="_7-决策矩阵-模式-×-能力" tabindex="-1">7. 决策矩阵：模式 × 能力 <a class="header-anchor" href="#_7-决策矩阵-模式-×-能力" aria-label="Permalink to &quot;7. 决策矩阵：模式 × 能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>observer</th><th>copilot</th><th>active</th><th>immersive</th></tr></thead><tbody><tr><td>AI 写动作（<code>needs_confirm=True</code>）</td><td>❌</td><td>✅ 逐项确认</td><td>✅ 逐项确认</td><td>⚠️ 可全自动</td></tr><tr><td><code>soft.*</code>（卫生规则）</td><td>❌</td><td>⚠️ 默认关；开则生效</td><td>✅</td><td>✅</td></tr><tr><td><code>app.*</code>（保存 / undo / why / pin / help）</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>⌘K LLM 意图</td><td>❌</td><td>⚠️ 默认关</td><td>⚠️ 默认关</td><td>⚠️ 默认关</td></tr><tr><td>Goal 规划</td><td>❌</td><td>⚠️ 默认关</td><td>⚠️ 默认关</td><td>⚠️ 默认关（全权时放行）</td></tr><tr><td>Ambient 提示</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Defer 重浮</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>战役自动</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>跨节改写</td><td>❌</td><td>⚠️ 需 <code>allow_dangerous</code></td><td>⚠️ 需 <code>allow_dangerous</code></td><td>✅ 全权时自动</td></tr><tr><td>Hard import</td><td>❌</td><td>❌</td><td>❌</td><td>✅ 全权时自动</td></tr><tr><td>出站 publish / git.push 等禁区</td><td>❌</td><td>❌</td><td>❌</td><td>❌ 恒拒绝</td></tr></tbody></table><p><code>❌</code> 硬阻 / <code>⚠️</code> 默认关需显式开 / <code>✅</code> 模式允许。</p><h2 id="_8-创作者不下放的边界" tabindex="-1">8. 创作者不下放的边界 <a class="header-anchor" href="#_8-创作者不下放的边界" aria-label="Permalink to &quot;8. 创作者不下放的边界&quot;">​</a></h2><p>无论模式如何，下列边界<strong>永久生效</strong>：</p><ol><li><strong>不删既有 id</strong>：AI 不得删除任何已发布的 id（课时 <code>s1-l1</code>、单元 <code>s1-u1</code>、节 <code>section1</code>、资源 <code>w-</code>/<code>e-</code>/<code>g-</code> 前缀等）。</li><li><strong>不跨语言引用</strong>：<code>tr</code> 课程不得引用其他语言课程的资源。</li><li><strong>不绕过 validate</strong>：所有 AI 写动作后必须 <code>CourseAdapter.save()</code> → <code>validate</code> → 失败回滚。</li><li><strong>不持久化 API Key</strong>：API Key 仅会话内存；关闭即销毁。</li><li><strong>不入出站 publish / git.push</strong>：<code>is_denied_immersive</code> 禁区在任何模式都拒绝。</li><li><strong>不静默替换已注册 runtimeType</strong>：替换为未注册类型时 validate 阻断。</li><li><strong>不删既有 vocab / expression / grammar_point</strong>：删除必须人工裁决。</li></ol><h2 id="_9-与-gui-主窗口的衔接" tabindex="-1">9. 与 GUI 主窗口的衔接 <a class="header-anchor" href="#_9-与-gui-主窗口的衔接" aria-label="Permalink to &quot;9. 与 GUI 主窗口的衔接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>行为</th></tr></thead><tbody><tr><td>状态栏「模式」chip</td><td>显示当前模式；点击下拉切换（切 Immersive 弹确认）</td></tr><tr><td>设置 → 体验 OS</td><td>模式 + Immersive 子开关 + 能力开关 + 日配额完整面板</td></tr><tr><td><code>Ctrl+Shift+D</code></td><td>一键降档回 <code>copilot</code>，并使未完成的 auto-apply token 失效</td></tr></tbody></table><p>状态栏常驻字段：模式 chip、AI 校验防护、今日 / 累计 token 与配额剩余、任务中模式警示。</p><h2 id="_10-相关文档" tabindex="-1">10. 相关文档 <a class="header-anchor" href="#_10-相关文档" aria-label="Permalink to &quot;10. 相关文档&quot;">​</a></h2><ul><li><a href="/docs/authoring/ai-course-generation">AI 课程生成</a> — 能力类 / 主路径 / 决策矩阵</li><li><a href="/docs/authoring/teacher-guide#ai-协作模式">教师指南 - AI 协作模式</a> — 教师视角的何时用 / 何时不用</li><li>应用仓库 <code>tool/gui/src/backend/experience/policy.py</code> — 四档与 PolicyDecision 唯一真源</li><li>应用仓库 <code>tool/gui/src/application/presence_mode.py</code> — Immersive 进入确认与一键降档</li></ul>`,53)])])}const b=e(i,[["render",s]]);export{_ as __pageData,b as default};
